# Analytical Raman Scattering Scaling (Efficiency ~ 1 / lambda^4)
LASERS_NM = {
    532:  ('Visible',  'High autofluorescence, poor penetration'),
    785:  ('NIR-Si',   'Sweet spot: low fluor + Si deep-depletion'),
    830:  ('NIR-Si',   'Clinical NIR: low fluor + Si deep-depletion'),
    1064: ('Deep-NIR', 'Minimal fluor, but noisier InGaAs sensor'),
}
for lam, (band, note) in LASERS_NM.items():
    rel_yield = (785.0 / lam) ** 4  # 532: 4.74x, 830: 0.80x, 1064: 0.30x
    print(f'{lam} nm [{band}]: {rel_yield:.2f}x vs 785 nm | {note}')
